# Let's try to solve the 4-coloring problem using z3 or backtracking
import sys

edges = [(0,2), (0,8), (0,22), (0,31), (1,4), (1,8), (1,15), (1,23), (2,4), (2,28), (2,31), (3,7), (3,17), (3,18), (3,21), (3,26), (4,24), (5,6), (5,13), (5,15), (5,18), (6,13), (6,15), (6,21), (6,24), (6,27), (6,29), (7,9), (7,16), (7,19), (7,24), (8,16), (8,20), (8,23), (9,20), (10,18), (10,22), (11,28), (12,16), (12,19), (12,23), (12,24), (12,29), (13,17), (13,25), (14,21), (15,19), (15,22), (15,29), (15,30), (16,22), (16,26), (17,22), (17,25), (17,30), (18,31), (19,23), (19,27), (20,30), (21,26), (21,31), (23,30), (23,31), (24,29), (27,31)]

n = 32
k = 4

# Try z3 first
try:
    from z3 import Solver, Int, And, Or, sat, Distinct

    s = Solver()
    colors = [Int(f'c{i}') for i in range(n)]

    # Domain constraints: each color in 0..3
    for c in colors:
        s.add(c >= 0, c <= 3)

    # Edge constraints: adjacent vertices have different colors
    for u, v in edges:
        s.add(colors[u] != colors[v])

    if s.check() == sat:
        m = s.model()
        solution = [m.evaluate(colors[i]).as_long() for i in range(n)]
        print("SAT")
        print(solution)
        # Verify
        ok = all(solution[u] != solution[v] for u, v in edges)
        print("Verified:", ok)
    else:
        print("UNSAT")

except ImportError:
    print("z3 not available, trying backtracking")

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def is_safe(v, c):
        for u in adj[v]:
            if colors[u] == c:
                return False
        return True

    def solve(v):
        if v == n:
            return True
        for c in range(k):
            if is_safe(v, c):
                colors[v] = c
                if solve(v + 1):
                    return True
                colors[v] = -1
        return False

    if solve(0):
        print("SAT")
        print(colors)
    else:
        print("UNSAT")
